import type {AvatarOrg, Role} from '@github-ui/role-assignments/types/role-assignments'
import type {AssigneeType} from '../enterprise-role-assignments-types'
import {testIdProps} from '@github-ui/test-id-props'
import {Text} from '@primer/react'
import styles from './NewRoleAssignmentRadio.module.css'
import {isEsm, esmStatus} from '../utils/role-utils'
import {NewRoleAssignmentRadio} from './NewRoleAssignmentRadio'
import {Blankslate} from '@primer/react/experimental'
import {NoteIcon} from '@primer/octicons-react'

export interface NewRoleAssignmentRadioGroupProps {
  roles: Role[]
  assigneeType: AssigneeType | undefined
  avatarOrgs?: AvatarOrg[]
  selectedRoleId: number | undefined
  enterpriseTeamOrgAssignmentLimitExceeded?: boolean
  onSelectCallback: (role: Role) => void
}

export function NewRoleAssignmentRadioGroup({
  roles,
  assigneeType,
  avatarOrgs,
  selectedRoleId,
  enterpriseTeamOrgAssignmentLimitExceeded,
  onSelectCallback,
}: NewRoleAssignmentRadioGroupProps) {
  function onRadioChange(selected: string | null) {
    const selectedRole = roles.find(role => role.id.toString() === selected)
    if (selectedRole) {
      onSelectCallback(selectedRole)
    }
  }

  return (
    <fieldset
      onChange={event => {
        const selected = (event.target as HTMLInputElement).value
        onRadioChange(selected)
      }}
      className={styles.radioGroup}
    >
      <legend className={styles.legend}>
        <Text size="medium" weight="semibold">
          Select role
        </Text>
      </legend>
      <div className={styles.container} {...testIdProps('role-assignment-list')}>
        <div className={styles.header}>
          <Text weight="semibold">{pluralize('role', roles.length)}</Text>
        </div>
        {roles.length === 0 ? (
          <Blankslate>
            <Blankslate.Visual>
              <NoteIcon size="medium" />
            </Blankslate.Visual>
            <Blankslate.Heading>You do not have any roles yet.</Blankslate.Heading>
          </Blankslate>
        ) : (
          <div>
            {roles.map(role => (
              <NewRoleAssignmentRadio
                key={role.id}
                role={role}
                roleStatus={isEsm(role) ? esmStatus(assigneeType, !!enterpriseTeamOrgAssignmentLimitExceeded) : null}
                checked={selectedRoleId === role.id}
                avatarOrgs={avatarOrgs}
              />
            ))}
          </div>
        )}
      </div>
    </fieldset>
  )
}

function pluralize(word: string, count: number) {
  return `${count} ${word}${count === 1 ? '' : 's'}`
}

try{ NewRoleAssignmentRadioGroup.displayName ||= 'NewRoleAssignmentRadioGroup' } catch {}