import {GitHubAvatar} from '@github-ui/github-avatar'
import {
  ActorType,
  RoleType,
  type ActorRoleAssignment,
  type AvatarEnterprise,
  type AvatarOrg,
} from '../types/role-assignments'
import {NestingTableRow} from './NestingTable/NestingTableRow'
import {RoleAssignmentsRoleDescriptionRow} from './RoleAssignmentsRoleDescriptionRow'

const pluralize = (word: string, count: number) => (count === 1 ? word : `${word}s`)

export function RoleAssignmentsTableRow({
  assignment,
  hasWriteAccess,
  showEnterpriseTeamLabel = false,
  canViewEnterpriseTeams,
  roleType,
  avatarOrgs,
  avatarEnterprise,
}: {
  assignment: ActorRoleAssignment
  hasWriteAccess: boolean
  showEnterpriseTeamLabel?: boolean
  canViewEnterpriseTeams: boolean
  roleType?: RoleType
  avatarOrgs?: AvatarOrg[]
  avatarEnterprise?: AvatarEnterprise
}) {
  return (
    <NestingTableRow
      leadingIcon={
        <GitHubAvatar
          size={16}
          alt={assignment.actor.name}
          src={assignment.actor.avatar_url}
          // circle if actor is a user, square if the actor is a team
          square={assignment.actor.type !== ActorType.User}
        />
      }
      title={assignment.actor.name}
      titleLabel={
        showEnterpriseTeamLabel && assignment.actor.type === ActorType.EnterpriseTeam ? 'Enterprise team' : ''
      }
      description={
        <span key="roles-count">
          {assignment.role_assignments.length} {pluralize('role', assignment.role_assignments.length)}
          {' assigned'}
          {assignment.actor.description && <>&nbsp;&nbsp;&bull;&nbsp;&nbsp;{assignment.actor.description}</>}
        </span>
      }
      subItems={assignment.role_assignments.map(roleAssignment => (
        <RoleAssignmentsRoleDescriptionRow
          actor={assignment.actor}
          roleType={roleType}
          roleAssignment={roleAssignment}
          hasWriteAccess={hasWriteAccess}
          canViewEnterpriseTeams={canViewEnterpriseTeams}
          key={roleAssignment.role.id}
          avatarOrgs={avatarOrgs}
          avatarEnterprise={avatarEnterprise}
        />
      ))}
      permalink={assignment.actor.permalink}
    />
  )
}

try{ RoleAssignmentsTableRow.displayName ||= 'RoleAssignmentsTableRow' } catch {}